import{_ as e,o as d,c as a,ae as c}from"./chunks/framework.B3uLoxsb.js";const p=JSON.parse('{"title":"为什么在 GPT Codex + VS Code 中使用 cw","description":"","frontmatter":{},"headers":[],"relativePath":"zh/strategy/why-cw.md","filePath":"zh/strategy/why-cw.md","lastUpdated":1771052491000}'),o={name:"zh/strategy/why-cw.md"};function l(i,t,r,h,s,w){return d(),a("div",null,[...t[0]||(t[0]=[c('<h1 id="为什么在-gpt-codex-vs-code-中使用-cw" tabindex="-1">为什么在 GPT Codex + VS Code 中使用 <code>cw</code> <a class="header-anchor" href="#为什么在-gpt-codex-vs-code-中使用-cw" aria-label="Permalink to &quot;为什么在 GPT Codex + VS Code 中使用 `cw`&quot;">​</a></h1><p>是的，这在专业 GitHub 仓库网站中很常见。</p><p>文档门户应该清楚说明：</p><ul><li>项目解决什么问题；</li><li>项目带来什么真实价值；</li><li>哪些场景下不必使用它。</li></ul><p>本页使用真实可验证的描述，不使用虚构效率数据。</p><h2 id="cw-解决的问题" tabindex="-1"><code>cw</code> 解决的问题 <a class="header-anchor" href="#cw-解决的问题" aria-label="Permalink to &quot;`cw` 解决的问题&quot;">​</a></h2><p>在较大项目中，如果没有统一执行模型，Codex 使用常见问题包括：</p><ul><li>团队成员提示词风格不一致；</li><li>计划、实现、验证之间衔接弱；</li><li>在交付压力下容易跳过治理和发布步骤；</li><li>不同仓库重复做同类 setup。</li></ul><h2 id="cw-带来的能力" tabindex="-1"><code>cw</code> 带来的能力 <a class="header-anchor" href="#cw-带来的能力" aria-label="Permalink to &quot;`cw` 带来的能力&quot;">​</a></h2><p><code>cw</code> 在 Codex 之上提供可复用执行模型：</p><ul><li>显式工作流触发（<code>cw /orchestrate</code>、<code>cw /debug</code> 等）；</li><li>codex-native 工作流契约；</li><li>按领域和技术栈的验证包（Node、Python、Rust）；</li><li>与仓库运维一致的 CI 与发布自动化；</li><li>多语言文档与操作手册。</li></ul><h2 id="对比-不用-cw-vs-使用-cw" tabindex="-1">对比：不用 <code>cw</code> vs 使用 <code>cw</code> <a class="header-anchor" href="#对比-不用-cw-vs-使用-cw" aria-label="Permalink to &quot;对比：不用 `cw` vs 使用 `cw`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>不用 <code>cw</code></th><th>使用 <code>cw</code></th></tr></thead><tbody><tr><td>任务启动</td><td>提示词方式因人而异</td><td>显式工作流触发 + 明确目标</td></tr><tr><td>多领域协作</td><td>协调方式临时化</td><td><code>/orchestrate</code> 分阶段协同</td></tr><tr><td>验证纪律</td><td>容易漏掉检查</td><td>内置验证流程与 CI 门禁</td></tr><tr><td>发布稳定性</td><td>手工流程，容易出错</td><td>自动化 tag/changelog/release</td></tr><tr><td>新人上手</td><td>知识分散在历史对话</td><td>文档、示例、命令集中</td></tr><tr><td>可复用性</td><td>依赖个人记忆</td><td>仓库级约定与检查</td></tr></tbody></table><h2 id="什么时候不必使用-cw" tabindex="-1">什么时候不必使用 <code>cw</code> <a class="header-anchor" href="#什么时候不必使用-cw" aria-label="Permalink to &quot;什么时候不必使用 `cw`&quot;">​</a></h2><p>对于非常小的一次性任务，直接使用 Codex 提示词通常足够。</p><p>当你需要以下能力时，<code>cw</code> 更有价值：</p><ul><li>多人协作一致性；</li><li>可审计的质量门禁；</li><li>可扩展的运维与发布节奏。</li></ul><h2 id="实践建议" tabindex="-1">实践建议 <a class="header-anchor" href="#实践建议" aria-label="Permalink to &quot;实践建议&quot;">​</a></h2><p>建议采用混合模式：</p><ol><li>小任务：直接提示词。</li><li>产品开发：<code>cw</code> 工作流 + 验证门禁。</li><li>发布周期：自动化检查 + 发布流水线。</li></ol>',20)])])}const u=e(o,[["render",l]]);export{p as __pageData,u as default};
